const data = msg.payload;

if (!data || !Array.isArray(data.value) || data.value.length === 0) {
    node.warn("No value found in SMHI response");
    return null;
}

const latest = data.value[data.value.length - 1];
const tempC = parseFloat(latest.value);

if (Number.isNaN(tempC)) {
    node.warn("Could not parse temperature value");
    return null;
}

const previousTimestamp = flow.get("lastObservedAtUTC");
const isNewValue = latest.date !== previousTimestamp;
flow.set("lastObservedAtUTC", latest.date);

const ageSeconds = Math.round((Date.now() - latest.date) / 1000);

if (!isNewValue && ageSeconds > 150) {
    node.status({ fill: "yellow", shape: "ring", text: `stale ${ageSeconds}s` });
} else {
    node.status({ fill: "green", shape: "dot", text: `${ageSeconds}s old` });
}


const utcDate = new Date(latest.date);
const localTime = utcDate.toLocaleString("sv-SE", {
    timeZone: "Europe/Stockholm",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit"
});

const freshness = isNewValue ? "new" : "unchanged";

msg.payload = tempC.toFixed(2).replace(".", ",");
msg.temperature = parseFloat(tempC.toFixed(2));
msg.observedAtUTC = latest.date;
msg.observedAtLocal = localTime;
msg.isNewValue = isNewValue;
msg.ageSeconds = ageSeconds;
msg.freshness = freshness;

return msg;
